1	/**
2	 * @module features/tv-dashboard/model/useTvDashboardData
3	 *
4	 * Hook principal da Torre de Controle da Operação (painel TV `/tv`).
5	 *
6	 * Paraleliza as fontes de dados via React Query:
7	 * - vendas live (edge `degust-pos-financial`/flash-vendas) — polling 60s;
8	 * - vendas defasadas Linx (`historico_vendas`, último dia disponível);
9	 * - comparativos: vs DIA ANTERIOR (principal, v3 — base pró-rateada p/ canal
10	 *   live) e vs MESMO DIA da semana passada (secundário);
11	 * - metas por loja × dia da semana (`metas_vendas`) com pró-rata da janela;
12	 * - alertas de estoque NOMEADOS (`estoque` × `produtos_master.ativo = true`);
13	 * - heartbeat + FEED nomeado de movimentações (`movimentacoes` de hoje);
14	 * - perdas no período do filtro global (`perdas`, R$ + itens + delta);
15	 * - compras no período (`notas_fiscais`, "gasto até hoje" + delta);
16	 * - produção da fábrica (`daily_production` com loja_id NULL).
17	 *
18	 * Nenhum `loja_id` é hardcoded: os canais são derivados em runtime de
19	 * `lojas` + `degust_stores` (Degust = live; demais lojas ativas = Linx
20	 * defasado; tipo "Fabrica" = card de fábrica).
21	 */
22	
23	import { useMemo } from 'react';
24	import { useQuery } from '@tanstack/react-query';
25	import { supabase } from '@/integrations/supabase/client';
26	import type {
27	  TvComprasSummary,
28	  TvDateRange,
29	  TvException,
30	  TvFactoryData,
31	  TvFactoryProduction,
32	  TvFreshness,
33	  TvMovementSummary,
34	  TvNetworkSummary,
35	  TvPerdasSummary,
36	  TvPeriod,
37	  TvRecentMove,
38	  TvSalesChannel,
39	  TvSalesSnapshot,
40	  TvStoreData,
41	  TvExceptionsResult,
42	} from './types';
43	import {
44	  FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
45	  TV_FACTORY_HOURS,
46	  TV_MINI_FEED_SIZE,
47	  addDays,
48	  aggregateCompras,
49	  aggregateMovements,
50	  aggregatePerdas,
51	  buildFreshness,
52	  buildNoMovementException,
53	  buildRecentMoves,
54	  buildStockExceptions,
55	  buildStockSummary,
56	  classifyStoreRag,
57	  fetchAllPages,
58	  parseIsoDateLocal,
59	  pctOfFullDayTarget,
60	  pctOfProRataTarget,
61	  periodRange,
62	  previousPeriodRange,
63	  proRataDayBase,
64	  rangeToLocalDayBounds,
65	  relativeDelta,
66	  remapFlashLojaIds,
67	  sortAndLimitExceptions,
68	  sortCriticalItems,
69	  toIsoDateLocal,
70	  weekOverWeekDelta,
71	  type ComprasByLoja,
72	  type FlashRow,
73	  type MovementAggregate,
74	  type MovementFeedRow,
75	  type PerdasAggregate,
76	  type PerdasByLoja,
77	  type StockDetail,
78	  type StockRow,
79	} from './tvMath';
80	import { useMinuteClock } from './useMinuteClock';
81	
82	// ─────────────────────────────────────────────────────────────────────────────
83	// Query keys + intervalos (exportados para o useTvRealtime invalidar)
84	// ─────────────────────────────────────────────────────────────────────────────
85	
86	/** Query keys do painel TV — usar SEMPRE estas referências para invalidar. */
87	export const tvDashboardKeys = {
88	  all: ['tv-dashboard'] as const,
89	  context: () => [...tvDashboardKeys.all, 'context'] as const,
90	  liveSales: () => [...tvDashboardKeys.all, 'live-sales'] as const,
91	  laggedSales: () => [...tvDashboardKeys.all, 'lagged-sales'] as const,
92	  /** Vendas de referência Degust (ontem + mesmo dia da semana passada). */
93	  referenceSales: () => [...tvDashboardKeys.all, 'reference-sales'] as const,
94	  metas: () => [...tvDashboardKeys.all, 'metas'] as const,
95	  stock: () => [...tvDashboardKeys.all, 'stock'] as const,
96	  movements: () => [...tvDashboardKeys.all, 'movements'] as const,
97	  /** Feed nomeado de movimentações de hoje (mini-feed "AGORA"). */
98	  movementFeed: () => [...tvDashboardKeys.all, 'movement-feed'] as const,
99	  /** Prefixo das perdas (invalidar TODOS os períodos de uma vez). */
100	  perdasRoot: () => [...tvDashboardKeys.all, 'perdas'] as const,
101	  perdas: (period: TvPeriod) => [...tvDashboardKeys.perdasRoot(), period] as const,
102	  /** Prefixo das compras (invalidar TODOS os períodos de uma vez). */
103	  comprasRoot: () => [...tvDashboardKeys.all, 'compras'] as const,
104	  compras: (period: TvPeriod) => [...tvDashboardKeys.comprasRoot(), period] as const,
105	  factoryProduction: () => [...tvDashboardKeys.all, 'factory-production'] as const,
106	  /** Prefixo do drill-down por loja (invalidar todas as lojas/ranges). */
107	  storeDetailRoot: () => [...tvDashboardKeys.all, 'store-detail'] as const,
108	  storeDetail: (lojaId: number, range: TvDateRange) =>
109	    [...tvDashboardKeys.storeDetailRoot(), lojaId, range.from, range.to] as const,
110	};
111	
112	// ─────────────────────────────────────────────────────────────────────────────
113	// Filtros canônicos de NF de compra (mesmo critério do módulo notas-fiscais)
114	// ─────────────────────────────────────────────────────────────────────────────
115	
116	/**
117	 * Status de NF que CONTAM como compra — mesmo critério do DRE
118	 * (`features/financeiro/ui/DREReport.tsx`): tudo menos `erro`. O campo de
119	 * data canônico é `data_nota` (emissão), idem DRE e filtro "data da nota"
120	 * da página de NFs.
121	 */
122	export const NF_COUNTED_STATUSES = ['processada', 'processando'] as const;
123	
124	/**
125	 * NFs de transferência interna (fornecedor "Momma Doces") NÃO são compra —
126	 * mesma exclusão da lista do módulo notas-fiscais (transferência ≠ NF de
127	 * compra; pertencem à aba Transferências).
128	 */
129	export const NF_TRANSFER_SUPPLIER_PATTERN = '%momma doces%';
130	
131	/** Intervalos de atualização (ms) por classe de dado. */
132	export const TV_QUERY_INTERVALS = {
133	  /** Vendas live: polling 60s (acceptance: atualização em até 60s). */
134	  liveMs: 60_000,
135	  /** Estoque/metas/movimentações/produção: 5min (+ Realtime invalida antes). */
136	  slowMs: 300_000,
137	} as const;
138	
139	// ─────────────────────────────────────────────────────────────────────────────
140	// Contexto: lojas + canais (derivados em runtime, sem hardcode de loja_id)
141	// ─────────────────────────────────────────────────────────────────────────────
142	
143	/** Loja ativa carregada no contexto do painel. */
144	export interface TvLoja {
145	  id: number;
146	  nome: string;
147	  tipo: string | null;
148	}
149	
150	/** Contexto runtime do painel (lojas + canais) — reusado pelo drill-down. */
151	export interface TvContext {
152	  lojas: TvLoja[];
153	  /** Lojas com venda live (existem em `degust_stores`). */
154	  degustLojaIds: Set<number>;
155	  /** Mapa código Degust → loja_id (corrige pass-through da edge function). */
156	  degustCodeToLoja: Map<number, number>;
157	  /** Lojas ativas de venda SEM integração live (canal Linx, defasado). */
158	  linxLojaIds: number[];
159	  /** Loja tipo fábrica (tipo "Fabrica", case-insensitive), ou null. */
160	  factoryLojaId: number | null;
161	}
162	
163	function isFactoryTipo(tipo: string | null): boolean {
164	  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
165	  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
166	}
167	
168	/** Carrega o contexto (exportado para o `useTvStoreDetail` compartilhar cache). */
169	export async function fetchTvContext(): Promise<TvContext> {
170	  const [lojasRes, degustRes] = await Promise.all([
171	    supabase
172	      .from('lojas')
173	      .select('id, nome, tipo')
174	      .eq('ativo', true)
175	      .order('id'),
176	    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
177	  ]);
178	  if (lojasRes.error) throw lojasRes.error;
179	  if (degustRes.error) throw degustRes.error;
180	
181	  const lojas: TvLoja[] = lojasRes.data ?? [];
182	  const degustLojaIds = new Set<number>();
183	  const degustCodeToLoja = new Map<number, number>();
184	  for (const row of degustRes.data ?? []) {
185	    degustLojaIds.add(row.loja_id);
186	    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
187	  }
188	
189	  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
190	  const linxLojaIds = lojas
191	    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
192	    .map((l) => l.id);
193	
194	  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
195	}
196	
197	// ─────────────────────────────────────────────────────────────────────────────
198	// Vendas live (edge degust-pos-financial / flash-vendas)
199	// ─────────────────────────────────────────────────────────────────────────────
200	
201	/** Contrato da edge `degust-pos-financial` (campos usados pelo painel). */
202	interface DegustPosFinancialResponse {
203	  flash?: Array<{
204	    loja_id: number;
205	    nome_loja: string;
206	    total_vendas: number;
207	    total_cupons: number;
208	    ticket_medio: number;
209	    qtd_produtos: number;
210	    caixa_aberto: boolean;
211	    ultima_atualizacao: string | null;
212	  }>;
213	}
214	
215	async function fetchLiveSales(ctx: TvContext): Promise<FlashRow[]> {
216	  const today = toIsoDateLocal(new Date());
217	  const { data, error } = await supabase.functions.invoke<DegustPosFinancialResponse>(
218	    'degust-pos-financial',
219	    { body: { startDate: today, endDate: today } },
220	  );
221	  if (error) throw error;
222	  const flash: FlashRow[] = (data?.flash ?? []).map((f) => ({
223	    loja_id: f.loja_id,
224	    nome_loja: f.nome_loja,
225	    total_vendas: f.total_vendas,
226	    total_cupons: f.total_cupons,
227	    ticket_medio: f.ticket_medio,
228	    caixa_aberto: f.caixa_aberto,
229	    ultima_atualizacao: f.ultima_atualizacao,
230	  }));
231	  return remapFlashLojaIds(flash, ctx.degustCodeToLoja, ctx.degustLojaIds);
232	}
233	
234	// ─────────────────────────────────────────────────────────────────────────────
235	// Vendas defasadas (Linx via historico_vendas — último dia disponível)
236	// ─────────────────────────────────────────────────────────────────────────────
237	
238	interface LaggedSales {
239	  lojaId: number;
240	  /** Último dia com venda registrada (YYYY-MM-DD). */
241	  dataReferencia: string;
242	  valor: number;
243	  quantidade: number;
244	  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
245	  valorSemanaAnterior: number | null;
246	  /** Valor do DIA ANTERIOR ao dia de referência (dias completos), ou null. */
247	  valorDiaAnterior: number | null;
248	}
249	
250	async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
251	  // 1) Último dia com dado para a loja
252	  const { data: latest, error: latestErr } = await supabase
253	    .from('historico_vendas')
254	    .select('data')
255	    .eq('loja_id', lojaId)
256	    .order('data', { ascending: false })
257	    .limit(1);
258	  if (latestErr) throw latestErr;
259	  const refDate = latest?.[0]?.data;
260	  if (!refDate) return null;
261	
262	  const weekAgoDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
263	  const dayBeforeDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -1));
264	
265	  // 2) Vendas do dia de referência + bases de comparação (dia anterior =
266	  //    comparativo PRINCIPAL v3; mesma semana = secundário)
267	  const [curRes, weekRes, dayRes] = await Promise.all([
268	    supabase
269	      .from('historico_vendas')
270	      .select('valor_total, quantidade')
271	      .eq('loja_id', lojaId)
272	      .eq('data', refDate)
273	      .limit(2000),
274	    supabase
275	      .from('historico_vendas')
276	      .select('valor_total')
277	      .eq('loja_id', lojaId)
278	      .eq('data', weekAgoDate)
279	      .limit(2000),
280	    supabase
281	      .from('historico_vendas')
282	      .select('valor_total')
283	      .eq('loja_id', lojaId)
284	      .eq('data', dayBeforeDate)
285	      .limit(2000),
286	  ]);
287	  if (curRes.error) throw curRes.error;
288	  if (weekRes.error) throw weekRes.error;
289	  if (dayRes.error) throw dayRes.error;
290	
291	  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
292	  const quantidade = (curRes.data ?? []).reduce(
293	    (s, r) => s + (r.quantidade ?? 0),
294	    0,
295	  );
296	  const sumOrNull = (rows: Array<{ valor_total: number | null }> | null) => {
297	    const list = rows ?? [];
298	    return list.length > 0
299	      ? list.reduce((s, r) => s + (r.valor_total ?? 0), 0)
300	      : null;
301	  };
302	
303	  return {
304	    lojaId,
305	    dataReferencia: refDate,
306	    valor,
307	    quantidade,
308	    valorSemanaAnterior: sumOrNull(weekRes.data),
309	    valorDiaAnterior: sumOrNull(dayRes.data),
310	  };
311	}
312	
313	async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
314	  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
315	  return results.filter((r): r is LaggedSales => r !== null);
316	}
317	
318	// ─────────────────────────────────────────────────────────────────────────────
319	// Bases de comparação Degust: ONTEM (principal v3) + mesmo dia da semana
320	// passada (secundário) — uma única query em degust_vendas_diarias
321	// ─────────────────────────────────────────────────────────────────────────────
322	
323	interface DegustReferenceSales {
324	  /** R$ por loja ONTEM (base do delta principal, pró-rateada no uso). */
325	  yesterday: Map<number, number>;
326	  /** R$ por loja no MESMO DIA da semana passada (delta secundário). */
327	  lastWeek: Map<number, number>;
328	}
329	
330	async function fetchDegustReference(ctx: TvContext): Promise<DegustReferenceSales> {
331	  const yesterday = new Map<number, number>();
332	  const lastWeek = new Map<number, number>();
333	  const ids = [...ctx.degustLojaIds];
334	  if (ids.length === 0) return { yesterday, lastWeek };
335	  const now = new Date();
336	  const yesterdayDate = toIsoDateLocal(addDays(now, -1));
337	  const lastWeekDate = toIsoDateLocal(addDays(now, -7));
338	  // Paginado: degust_vendas_diarias é linha-por-produto (2 dias × N lojas
339	  // pode passar de 1000 — o PostgREST cortaria silenciosamente).
340	  const rows = await fetchAllPages((from, to) =>
341	    supabase
342	      .from('degust_vendas_diarias')
343	      .select('loja_id, valor_total, data')
344	      .in('data', [yesterdayDate, lastWeekDate])
345	      .in('loja_id', ids)
346	      .order('id')
347	      .range(from, to),
348	  );
349	  for (const row of rows) {
350	    const target = row.data === yesterdayDate ? yesterday : lastWeek;
351	    target.set(row.loja_id, (target.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
352	  }
353	  return { yesterday, lastWeek };
354	}
355	
356	// ─────────────────────────────────────────────────────────────────────────────
357	// Metas (loja × dia da semana, convenção JS Date.getDay(): 0=domingo)
358	// ─────────────────────────────────────────────────────────────────────────────
359	
360	async function fetchMetas(): Promise<Map<string, number>> {
361	  const { data, error } = await supabase
362	    .from('metas_vendas')
363	    .select('loja_id, dia_semana, valor_meta')
364	    .limit(1000);
365	  if (error) throw error;
366	  const out = new Map<string, number>();
367	  for (const row of data ?? []) {
368	    out.set(`${row.loja_id}:${row.dia_semana}`, row.valor_meta);
369	  }
370	  return out;
371	}
372	
373	function metaFor(
374	  metas: Map<string, number> | undefined,
375	  lojaId: number,
376	  date: Date,
377	): number | null {
378	  if (!metas) return null;
379	  return metas.get(`${lojaId}:${date.getDay()}`) ?? null;
380	}
381	
382	// ─────────────────────────────────────────────────────────────────────────────
383	// Estoque em alerta (JOIN com produtos ATIVOS — regra dura do projeto)
384	// ─────────────────────────────────────────────────────────────────────────────
385	
386	/** Exportado para o `useTvStoreDetail` compartilhar a MESMA query/cache. */
387	export async function fetchStockAlerts(): Promise<StockRow[]> {
388	  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
389	  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas
390	  // candidatas hoje). Paginação obrigatória: o PostgREST corta em 1000 linhas
391	  // mesmo com `.limit()` maior — `.order('id')` garante páginas estáveis.
392	  const data = await fetchAllPages((from, to) =>
393	    supabase
394	      .from('estoque')
395	      .select(
396	        'loja_id, quantidade_atual, quantidade_minima, produto_master:produtos_master!inner(nome, ativo)',
397	      )
398	      .eq('produto_master.ativo', true)
399	      .gt('quantidade_minima', 0)
400	      .or('oculto.is.null,oculto.eq.false')
401	      .order('id')
402	      .range(from, to),
403	  );
404	  return data.map((row) => ({
405	    loja_id: row.loja_id,
406	    quantidade_atual: row.quantidade_atual,
407	    quantidade_minima: row.quantidade_minima,
408	    produtoNome: row.produto_master?.nome ?? '(sem nome)',
409	  }));
410	}
411	
412	// ─────────────────────────────────────────────────────────────────────────────
413	// Movimentações de hoje (heartbeat por loja)
414	// ─────────────────────────────────────────────────────────────────────────────
415	
416	async function fetchMovementsToday(): Promise<Map<number, MovementAggregate>> {
417	  const startOfDay = new Date();
418	  startOfDay.setHours(0, 0, 0, 0);
419	  // Pico real >1k movimentações/dia: paginar (PostgREST corta em 1000).
420	  const data = await fetchAllPages((from, to) =>
421	    supabase
422	      .from('movimentacoes')
423	      .select('loja_id, tipo_movimentacao, data_movimentacao')
424	      .gte('data_movimentacao', startOfDay.toISOString())
425	      .order('id')
426	      .range(from, to),
427	  );
428	  return aggregateMovements(data);
429	}
430	
431	// ─────────────────────────────────────────────────────────────────────────────
432	// Feed nomeado de movimentações de hoje (mini-feed "AGORA" por coluna)
433	// ─────────────────────────────────────────────────────────────────────────────
434	
435	/**
436	 * Quantas linhas o feed busca de uma vez. NÃO pagina de propósito: é um
437	 * feed "AGORA" (últimas {@link TV_MINI_FEED_SIZE} por unidade) — query
438	 * separada dos AGREGADOS (que seguem paginados via fetchAllPages). Em dia
439	 * de pico (acima de 150 movimentações) uma unidade parada há muitas horas
440	 * pode ficar sem mini-feed — aceitável: o card já mostra "última bipagem".
441	 */
442	const TV_FEED_FETCH_LIMIT = 150;
443	
444	/** Forma da linha de `movimentacoes` com o join de nome do produto. */
445	interface MovementFeedQueryRow {
446	  loja_id: number | null;
447	  tipo_movimentacao: string;
448	  data_movimentacao: string | null;
449	  quantidade: number | null;
450	  produto_master: { nome: string } | null;
451	}
452	
453	function toFeedRows(rows: MovementFeedQueryRow[]): MovementFeedRow[] {
454	  // Feed mostra TODA movimentação (evento operacional aconteceu, produto
455	  // ativo ou não) — diferente das listas de produto, que filtram ativo=true.
456	  return rows.map((r) => ({
457	    loja_id: r.loja_id,
458	    tipo_movimentacao: r.tipo_movimentacao,
459	    data_movimentacao: r.data_movimentacao,
460	    quantidade: r.quantidade,
461	    produtoNome: r.produto_master?.nome ?? '(sem produto)',
462	  }));
463	}
464	
465	async function fetchMovementFeed(): Promise<Map<number, TvRecentMove[]>> {
466	  const startOfDay = new Date();
467	  startOfDay.setHours(0, 0, 0, 0);
468	  const { data, error } = await supabase
469	    .from('movimentacoes')
470	    .select(
471	      'loja_id, tipo_movimentacao, data_movimentacao, quantidade, produto_master:produtos_master(nome)',
472	    )
473	    .gte('data_movimentacao', startOfDay.toISOString())
474	    .order('data_movimentacao', { ascending: false })
475	    .limit(TV_FEED_FETCH_LIMIT);
476	  if (error) throw error;
477	  return buildRecentMoves(toFeedRows(data ?? []), TV_MINI_FEED_SIZE);
478	}
479	
480	// ─────────────────────────────────────────────────────────────────────────────
481	// Perdas no período do filtro global (tabela `perdas`)
482	// ─────────────────────────────────────────────────────────────────────────────
483	
484	/** Par período corrente + período anterior equivalente (comparativo). */
485	export interface PeriodedAggregates<T> {
486	  current: T;
487	  previous: T;
488	}
489	
490	async function loadPerdasRange(range: TvDateRange): Promise<PerdasByLoja> {
491	  const bounds = rangeToLocalDayBounds(range);
492	  // Paginado: um mês de perdas pode passar de 1000 linhas (corte silencioso
493	  // do PostgREST). `data_identificacao` é timestamptz → bounds de dia local.
494	  const rows = await fetchAllPages((from, to) =>
495	    supabase
496	      .from('perdas')
497	      .select('loja_id, valor_estimado')
498	      .gte('data_identificacao', bounds.startIso)
499	      .lt('data_identificacao', bounds.endExclusiveIso)
500	      .order('id')
501	      .range(from, to),
502	  );
503	  return aggregatePerdas(rows);
504	}
505	
506	async function fetchPerdasAggregates(
507	  period: TvPeriod,
508	): Promise<PeriodedAggregates<PerdasByLoja>> {
509	  const now = new Date();
510	  const [current, previous] = await Promise.all([
511	    loadPerdasRange(periodRange(period, now)),
512	    loadPerdasRange(previousPeriodRange(period, now)),
513	  ]);
514	  return { current, previous };
515	}
516	
517	// ─────────────────────────────────────────────────────────────────────────────
518	// Compras no período do filtro global (notas_fiscais — "gasto até hoje")
519	// ─────────────────────────────────────────────────────────────────────────────
520	
521	async function loadComprasRange(range: TvDateRange): Promise<ComprasByLoja> {
522	  // Campo de data canônico: `data_nota` (emissão) — mesmo critério do DRE.
523	  // Status válido = tudo menos `erro` (NF_COUNTED_STATUSES); transferências
524	  // internas "Momma Doces" excluídas (não são compra). Paginado: um mês de
525	  // NFs pode passar de 1000 linhas.
526	  const rows = await fetchAllPages((from, to) =>
527	    supabase
528	      .from('notas_fiscais')
529	      .select('loja_id, valor_total')
530	      .gte('data_nota', range.from)
531	      .lte('data_nota', range.to)
532	      .in('status', [...NF_COUNTED_STATUSES])
533	      .not('fornecedor', 'ilike', NF_TRANSFER_SUPPLIER_PATTERN)
534	      .order('id')
535	      .range(from, to),
536	  );
537	  return aggregateCompras(rows);
538	}
539	
540	async function fetchComprasAggregates(
541	  period: TvPeriod,
542	): Promise<PeriodedAggregates<ComprasByLoja>> {
543	  const now = new Date();
544	  const [current, previous] = await Promise.all([
545	    loadComprasRange(periodRange(period, now)),
546	    loadComprasRange(previousPeriodRange(period, now)),
547	  ]);
548	  return { current, previous };
549	}
