551	// ─────────────────────────────────────────────────────────────────────────────
552	// Produção da fábrica (daily_production com loja_id NULL = fábrica)
553	// ─────────────────────────────────────────────────────────────────────────────
554	
555	async function fetchFactoryProduction(): Promise<TvFactoryProduction | null> {
556	  const today = toIsoDateLocal(new Date());
557	
558	  const loadDay = async (date: string) => {
559	    const { data, error } = await supabase
560	      .from('daily_production')
561	      .select('quantity')
562	      .is('loja_id', null)
563	      .eq('date', date)
564	      .limit(2000);
565	    if (error) throw error;
566	    return data ?? [];
567	  };
568	
569	  let refDate = today;
570	  let rows = await loadDay(today);
571	  if (rows.length === 0) {
572	    // Sem produção registrada hoje → mostra o último dia disponível
573	    const { data: latest, error } = await supabase
574	      .from('daily_production')
575	      .select('date')
576	      .is('loja_id', null)
577	      .lte('date', today)
578	      .order('date', { ascending: false })
579	      .limit(1);
580	    if (error) throw error;
581	    const lastDate = latest?.[0]?.date;
582	    if (!lastDate) return null;
583	    refDate = lastDate;
584	    rows = await loadDay(lastDate);
585	  }
586	
587	  return {
588	    dataReferencia: refDate,
589	    itens: rows.length,
590	    totalUnidades: rows.reduce((s, r) => s + (r.quantity ?? 0), 0),
591	  };
592	}
