598	/** Retorno do {@link useTvDashboardData}. */
599	export interface TvDashboardData {
600	  network: TvNetworkSummary | null;
601	  stores: TvStoreData[];
602	  factory: TvFactoryData | null;
603	  exceptions: TvExceptionsResult;
604	  freshness: TvFreshness;
605	  /** Período do filtro global aplicado a perdas/compras/comparativos. */
606	  period: TvPeriod;
607	  /** Range corrente do filtro (para rótulos na UI). */
608	  range: TvDateRange;
609	  /** Range anterior equivalente usado nos comparativos. */
610	  previousRange: TvDateRange;
611	  /** true enquanto o contexto (lojas/canais) ainda não carregou. */
612	  isLoading: boolean;
613	  /** true quando o contexto falhou (painel não consegue montar). */
614	  isError: boolean;
615	}
616	
617	const EMPTY_MOVEMENT: TvMovementSummary = {
618	  entradas: 0,
619	  saidas: 0,
620	  ultimaBipagem: null,
621	};
622	
623	const EMPTY_PERDAS_AGG: PerdasAggregate = { valor: 0, itens: 0 };
624	
625	/** Monta o resumo de perdas de UMA unidade a partir dos agregados. */
626	function perdasSummaryFor(
627	  agg: PeriodedAggregates<PerdasByLoja> | undefined,
628	  lojaId: number,
629	): TvPerdasSummary {
630	  const cur = agg?.current.byLoja.get(lojaId) ?? EMPTY_PERDAS_AGG;
631	  const prev = agg?.previous.byLoja.get(lojaId);
632	  return {
633	    valor: cur.valor,
634	    itens: cur.itens,
635	    deltaPct: relativeDelta(cur.valor, prev?.valor ?? null),
636	  };
637	}
638	
639	/** Monta o resumo de compras de UMA unidade a partir dos agregados. */
640	function comprasSummaryFor(
641	  agg: PeriodedAggregates<ComprasByLoja> | undefined,
642	  lojaId: number,
643	): TvComprasSummary {
644	  const cur = agg?.current.byLoja.get(lojaId) ?? 0;
645	  const prev = agg?.previous.byLoja.get(lojaId);
646	  return { valor: cur, deltaPct: relativeDelta(cur, prev ?? null) };
647	}
