649	/**
650	 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
651	 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
652	 * `freshness`). Vendas live re-buscam a cada 60s; o resto a
653	 * cada 5min (com invalidação antecipada via {@link useTvRealtime}).
654	 *
655	 * @param period - Filtro global Hoje/Semana/Mês — muda perdas, compras e
656	 *   seus comparativos. Vendas dos cards são SEMPRE de hoje (+ % vs ontem).
657	 */
658	export function useTvDashboardData(period: TvPeriod = 'today'): TvDashboardData {
659	  // "now" que AVANÇA (tick de minuto): staleness/RAG/pró-rata reclassificam
660	  // mesmo quando NENHUMA query devolve dado novo (outage total). Sem isso o
661	  // chip ficaria "✓ ao vivo" pra sempre com tudo fora do ar.
662	  const tick = useMinuteClock();
663	
664	  const ctxQuery = useQuery({
665	    queryKey: tvDashboardKeys.context(),
666	    queryFn: fetchTvContext,
667	    staleTime: TV_QUERY_INTERVALS.slowMs,
668	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
669	  });
670	  const ctx = ctxQuery.data;
671	
672	  const liveQuery = useQuery({
673	    queryKey: tvDashboardKeys.liveSales(),
674	    queryFn: () => {
675	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
676	      return fetchLiveSales(ctx);
677	    },
678	    enabled: !!ctx,
679	    refetchInterval: TV_QUERY_INTERVALS.liveMs,
680	    staleTime: 30_000,
681	  });
682	
683	  const laggedQuery = useQuery({
684	    queryKey: tvDashboardKeys.laggedSales(),
685	    queryFn: () => {
686	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
687	      return fetchLaggedSales(ctx);
688	    },
689	    enabled: !!ctx,
690	    staleTime: TV_QUERY_INTERVALS.slowMs,
691	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
692	  });
693	
694	  const referenceQuery = useQuery({
695	    queryKey: tvDashboardKeys.referenceSales(),
696	    queryFn: () => {
697	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
698	      return fetchDegustReference(ctx);
699	    },
700	    enabled: !!ctx,
701	    staleTime: TV_QUERY_INTERVALS.slowMs,
702	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
703	  });
704	
705	  const perdasQuery = useQuery({
706	    queryKey: tvDashboardKeys.perdas(period),
707	    queryFn: () => fetchPerdasAggregates(period),
708	    staleTime: TV_QUERY_INTERVALS.slowMs,
709	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
710	  });
711	
712	  const comprasQuery = useQuery({
713	    queryKey: tvDashboardKeys.compras(period),
714	    queryFn: () => fetchComprasAggregates(period),
715	    staleTime: TV_QUERY_INTERVALS.slowMs,
716	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
717	  });
718	
719	  const feedQuery = useQuery({
720	    queryKey: tvDashboardKeys.movementFeed(),
721	    queryFn: fetchMovementFeed,
722	    staleTime: TV_QUERY_INTERVALS.slowMs,
723	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
724	  });
725	
726	  const metasQuery = useQuery({
727	    queryKey: tvDashboardKeys.metas(),
728	    queryFn: fetchMetas,
729	    staleTime: TV_QUERY_INTERVALS.slowMs,
730	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
731	  });
732	
733	  const stockQuery = useQuery({
734	    queryKey: tvDashboardKeys.stock(),
735	    queryFn: fetchStockAlerts,
736	    staleTime: TV_QUERY_INTERVALS.slowMs,
737	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
738	  });
739	
740	  const movementsQuery = useQuery({
741	    queryKey: tvDashboardKeys.movements(),
742	    queryFn: fetchMovementsToday,
743	    staleTime: TV_QUERY_INTERVALS.slowMs,
744	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
745	  });
746	
747	  const factoryQuery = useQuery({
748	    queryKey: tvDashboardKeys.factoryProduction(),
749	    queryFn: fetchFactoryProduction,
750	    staleTime: TV_QUERY_INTERVALS.slowMs,
751	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
752	  });
753	
754	  return useMemo<TvDashboardData>(() => {
755	    const now = tick;
756	    const todayIso = toIsoDateLocal(now);
757	    const range = periodRange(period, now);
758	    const previousRange = previousPeriodRange(period, now);
759	
760	    const stockDetail: Map<number, StockDetail> = buildStockSummary(
761	      stockQuery.data ?? [],
762	    );
763	    const movements = movementsQuery.data ?? new Map<number, MovementAggregate>();
764	    const feedByLoja = feedQuery.data ?? new Map<number, TvRecentMove[]>();
765	    const flashByLoja = new Map<number, FlashRow>(
766	      (liveQuery.data ?? []).map((f) => [f.loja_id, f]),
767	    );
768	    const laggedByLoja = new Map<number, LaggedSales>(
769	      (laggedQuery.data ?? []).map((l) => [l.lojaId, l]),
770	    );
771	    const lastWeekByLoja = referenceQuery.data?.lastWeek ?? new Map<number, number>();
772	    const yesterdayByLoja = referenceQuery.data?.yesterday ?? new Map<number, number>();
773	    const perdasAgg = perdasQuery.data;
774	    const comprasAgg = comprasQuery.data;
775	    const lojaNomeById = new Map<number, string>(
776	      (ctx?.lojas ?? []).map((l) => [l.id, l.nome]),
777	    );
778	
779	    // ── Cards de loja ──
780	    const stores: TvStoreData[] = (ctx?.lojas ?? [])
781	      .filter((l) => !isFactoryTipo(l.tipo))
782	      .map((loja) => {
783	        const channel: TvSalesChannel = ctx?.degustLojaIds.has(loja.id)
784	          ? 'degust-live'
785	          : 'linx-lagged';
786	        const stock = stockDetail.get(loja.id);
787	        const movement = movements.get(loja.id) ?? EMPTY_MOVEMENT;
788	
789	        let vendas: TvSalesSnapshot | null = null;
790	        let metaDia: number | null = null;
791	        let pctMeta: number | null = null;
792	        let deltaSemana: number | null = null;
793	        let deltaOntem: number | null = null;
794	
795	        if (channel === 'degust-live') {
796	          const flash = flashByLoja.get(loja.id);
797	          if (flash) {
798	            vendas = {
799	              valor: flash.total_vendas,
800	              cupons: flash.total_cupons,
801	              ticketMedio: flash.ticket_medio,
802	              dataReferencia: todayIso,
803	              isLive: true,
804	              caixaAberto: flash.caixa_aberto,
805	              atualizadoEm: flash.ultima_atualizacao,
806	            };
807	            metaDia = metaFor(metasQuery.data, loja.id, now);
808	            pctMeta = pctOfProRataTarget(flash.total_vendas, metaDia, now);
809	            // Deltas live = "vs MESMO PONTO do dia de referência": a base
810	            // (ontem = PRINCIPAL v3; semana passada = secundário) é
811	            // pró-rateada pela fração da janela já decorrida (mesma fração
812	            // do pró-rata da meta). Comparar hoje PARCIAL com dia COMPLETO
813	            // inflava a queda de manhã.
814	            deltaOntem = relativeDelta(
815	              flash.total_vendas,
816	              proRataDayBase(yesterdayByLoja.get(loja.id) ?? null, now),
817	            );
818	            deltaSemana = weekOverWeekDelta(
819	              flash.total_vendas,
820	              proRataDayBase(lastWeekByLoja.get(loja.id) ?? null, now),
821	            );
822	          }
823	        } else {
824	          const lagged = laggedByLoja.get(loja.id);
825	          if (lagged) {
826	            vendas = {
827	              valor: lagged.valor,
828	              cupons: null,
829	              ticketMedio: null,
830	              dataReferencia: lagged.dataReferencia,
831	              isLive: false,
832	              caixaAberto: null,
833	              atualizadoEm: null,
834	            };
835	            // Meta do dia da semana do DIA DE REFERÊNCIA (já encerrado → sem pró-rata)
836	            const refDate = parseIsoDateLocal(lagged.dataReferencia);
837	            metaDia = metaFor(metasQuery.data, loja.id, refDate);
838	            pctMeta = pctOfFullDayTarget(lagged.valor, metaDia);
839	            // Canal defasado: dia COMPLETO vs dia COMPLETO — sem pró-rata.
840	            // Principal v3 = vs dia ANTERIOR ao de referência.
841	            deltaOntem = relativeDelta(lagged.valor, lagged.valorDiaAnterior);
842	            deltaSemana = weekOverWeekDelta(
843	              lagged.valor,
844	              lagged.valorSemanaAnterior,
845	            );
846	          }
847	        }
848	
849	        const rag = classifyStoreRag({
850	          stockOutCount: stock?.zerados ?? 0,
851	          stockLowCount: stock?.abaixoMinimo ?? 0,
852	          pctMetaProRata: channel === 'degust-live' ? pctMeta : null,
853	          isLiveChannel: channel === 'degust-live',
854	          lastMovementAt: movement.ultimaBipagem,
855	          now,
856	        });
857	
858	        return {
859	          lojaId: loja.id,
860	          nome: loja.nome,
861	          channel,
862	          vendas,
863	          metaDia,
864	          pctMeta,
865	          deltaSemana,
866	          deltaOntem,
867	          estoque: {
868	            zerados: stock?.zerados ?? 0,
869	            abaixoMinimo: stock?.abaixoMinimo ?? 0,
870	          },
871	          movimentacao: movement,
872	          perdas: perdasSummaryFor(perdasAgg, loja.id),
873	          compras: comprasSummaryFor(comprasAgg, loja.id),
874	          criticalItems: sortCriticalItems(stock?.itens ?? []),
875	          recentMoves: feedByLoja.get(loja.id) ?? [],
876	          rag: rag.status,
877	          ragReasons: rag.reasons,
878	        };
879	      });
880	
881	    // ── Card da fábrica ──
882	    let factory: TvFactoryData | null = null;
883	    if (ctx?.factoryLojaId != null) {
884	      const fid = ctx.factoryLojaId;
885	      const stock = stockDetail.get(fid);
886	      const movement = movements.get(fid) ?? EMPTY_MOVEMENT;
887	      const rag = classifyStoreRag({
888	        stockOutCount: stock?.zerados ?? 0,
889	        stockLowCount: stock?.abaixoMinimo ?? 0,
890	        pctMetaProRata: null,
891	        isLiveChannel: false,
892	        lastMovementAt: movement.ultimaBipagem,
893	        now,
894	        // Janela de PRODUÇÃO (06–18h, threshold 2h) — mesma do card visual
895	        hours: TV_FACTORY_HOURS,
896	        noMovementThresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
897	      });
898	      factory = {
899	        lojaId: fid,
900	        nome: lojaNomeById.get(fid) ?? 'Fábrica',
901	        producao: factoryQuery.data ?? null,
902	        expedicoes: movement,
903	        estoque: {
904	          zerados: stock?.zerados ?? 0,
905	          abaixoMinimo: stock?.abaixoMinimo ?? 0,
906	        },
907	        perdas: perdasSummaryFor(perdasAgg, fid),
908	        compras: comprasSummaryFor(comprasAgg, fid),
909	        criticalItems: sortCriticalItems(stock?.itens ?? []),
910	        recentMoves: feedByLoja.get(fid) ?? [],
911	        rag: rag.status,
912	        ragReasons: rag.reasons,
913	      };
914	    }
915	
916	    // ── Freshness ──
917	    // Classificada com `now` do tick de minuto: quando dataUpdatedAt para de
918	    // avançar (outage), a idade cresce e o chip escala pra âmbar mesmo sem
919	    // nenhum dado novo chegar. Os timestamps CRUS ficam expostos no retorno.
920	    const freshness: TvFreshness = buildFreshness(
921	      liveQuery.dataUpdatedAt,
922	      stockQuery.dataUpdatedAt,
923	      TV_QUERY_INTERVALS,
924	      now,
925	    );
926	
927	    // ── Exceções (vermelho > âmbar, máx 7 + excedente) ──
928	    const allExceptions: TvException[] = buildStockExceptions(
929	      stockDetail,
930	      lojaNomeById,
931	    );
932	    // "Sem movimentação" derivada do DADO estruturado (última bipagem ×
933	    // janela), nunca por parsing de ragReasons — independe da cor do card
934	    // (aparece mesmo com card vermelho) e cobre também a fábrica.
935	    for (const store of stores) {
936	      const noMovement = buildNoMovementException({
937	        lojaId: store.lojaId,
938	        lojaNome: store.nome,
939	        lastMovementAt: store.movimentacao.ultimaBipagem,
940	        now,
941	      });
942	      if (noMovement) allExceptions.push(noMovement);
943	    }
944	    if (factory) {
945	      const noMovement = buildNoMovementException({
946	        lojaId: factory.lojaId,
947	        lojaNome: factory.nome,
948	        lastMovementAt: factory.expedicoes.ultimaBipagem,
949	        now,
950	        hours: TV_FACTORY_HOURS,
951	        thresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
952	      });
953	      if (noMovement) allExceptions.push(noMovement);
954	    }
955	    if (freshness.vendasLive.level !== 'fresh' && (ctx?.degustLojaIds.size ?? 0) > 0) {
956	      const liveUpdatedAt = freshness.vendasLive.updatedAt;
957	      allExceptions.push({
958	        id: 'stale-data:vendas-live',
959	        kind: 'stale-data',
960	        severity: 'amber',
961	        lojaId: null,
962	        lojaNome: null,
963	        message: liveUpdatedAt
964	          ? `Venda live sem atualização desde ${new Date(liveUpdatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
965	          : 'Venda live ainda não carregou',
966	      });
967	    }
968	    const exceptions = sortAndLimitExceptions(allExceptions);
969	
970	    // ── Hero (rede) ──
971	    // Soma apenas lojas cujo dado é de HOJE (live) — não misturar dias.
972	    const liveStores = stores.filter(
973	      (s) => s.vendas?.isLive && s.vendas.dataReferencia === todayIso,
974	    );
975	    const vendasHoje = liveStores.reduce((s, st) => s + (st.vendas?.valor ?? 0), 0);
976	    const metasHoje = liveStores
977	      .map((s) => s.metaDia)
978	      .filter((m): m is number => m != null && m > 0);
979	    const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;
980	    const lastWeekTotal = liveStores.reduce(
981	      (s, st) => s + (lastWeekByLoja.get(st.lojaId) ?? 0),
982	      0,
983	    );
984	    const yesterdayTotal = liveStores.reduce(
985	      (s, st) => s + (yesterdayByLoja.get(st.lojaId) ?? 0),
986	      0,
987	    );
988	    const network: TvNetworkSummary | null = ctx
989	      ? {
990	          vendasHoje,
991	          metaDia,
992	          pctMetaProRata: pctOfProRataTarget(vendasHoje, metaDia, now),
993	          // Mesmo critério do card live: deltas "vs mesmo ponto do dia de
994	          // referência" (base pró-rateada pela fração da janela). Ontem é
995	          // o PRINCIPAL (v3); semana passada segue como secundário.
996	          deltaSemana: weekOverWeekDelta(
997	            vendasHoje,
998	            proRataDayBase(lastWeekTotal, now),
999	          ),
1000	          deltaOntem: relativeDelta(
1001	            vendasHoje,
1002	            proRataDayBase(yesterdayTotal, now),
1003	          ),
1004	          // Totais da REDE: incluem linhas sem loja_id (não atribuíveis a
1005	          // nenhuma coluna — entram SOMENTE aqui).
1006	          perdas: {
1007	            valor: perdasAgg?.current.total.valor ?? 0,
1008	            itens: perdasAgg?.current.total.itens ?? 0,
1009	            deltaPct: relativeDelta(
1010	              perdasAgg?.current.total.valor ?? 0,
1011	              perdasAgg?.previous.total.valor ?? null,
1012	            ),
1013	          },
1014	          compras: {
1015	            valor: comprasAgg?.current.total ?? 0,
1016	            deltaPct: relativeDelta(
1017	              comprasAgg?.current.total ?? 0,
1018	              comprasAgg?.previous.total ?? null,
1019	            ),
1020	          },
1021	          alertasCriticos: allExceptions.filter((e) => e.severity === 'red').length,
1022	          lojasLive: liveStores.length,
1023	          lojasDefasadas: stores.filter((s) => s.channel === 'linx-lagged').length,
1024	        }
1025	      : null;
1026	
1027	    return {
1028	      network,
1029	      stores,
1030	      factory,
1031	      exceptions,
1032	      freshness,
1033	      period,
1034	      range,
1035	      previousRange,
1036	      isLoading: ctxQuery.isLoading,
1037	      isError: ctxQuery.isError,
1038	    };
1039	  }, [
1040	    // `tick` é o que faz staleness/RAG avançarem em outage total (sem ele a
1041	    // classificação congelaria no último snapshot de dados).
1042	    tick,
1043	    period,
1044	    ctx,
1045	    ctxQuery.isLoading,
1046	    ctxQuery.isError,
1047	    liveQuery.data,
1048	    liveQuery.dataUpdatedAt,
1049	    laggedQuery.data,
1050	    referenceQuery.data,
1051	    metasQuery.data,
1052	    stockQuery.data,
1053	    stockQuery.dataUpdatedAt,
1054	    movementsQuery.data,
1055	    feedQuery.data,
1056	    perdasQuery.data,
1057	    comprasQuery.data,
1058	    factoryQuery.data,
1059	  ]);
