69	// ─────────────────────────────────────────────────────────────────────────────
70	// Datas (helpers locais, sem dependência de timezone UTC)
71	// ─────────────────────────────────────────────────────────────────────────────
72	
73	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
74	export function toIsoDateLocal(d: Date): string {
75	  const y = d.getFullYear();
76	  const m = String(d.getMonth() + 1).padStart(2, '0');
77	  const day = String(d.getDate()).padStart(2, '0');
78	  return `${y}-${m}-${day}`;
79	}
80	
81	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
82	export function parseIsoDateLocal(iso: string): Date {
83	  const [y, m, d] = iso.split('-').map(Number);
84	  return new Date(y, (m ?? 1) - 1, d ?? 1);
85	}
86	
87	/** Soma `days` dias a uma data, retornando nova instância. */
88	export function addDays(d: Date, days: number): Date {
89	  const out = new Date(d);
90	  out.setDate(out.getDate() + days);
91	  return out;
92	}
93	
94	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
95	export function formatLaggedDateLabel(isoDate: string): string {
96	  const d = parseIsoDateLocal(isoDate);
97	  const dd = String(d.getDate()).padStart(2, '0');
98	  const mm = String(d.getMonth() + 1).padStart(2, '0');
99	  return `até ${dd}/${mm}`;
100	}
101	
102	/**
103	 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
104	 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
105	 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
106	 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
107	 */
108	export function parseBrDateTime(value: string | null | undefined): Date | null {
109	  if (!value) return null;
110	  const m = value.match(
111	    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
112	  );
113	  if (m) {
114	    const [, dd, mm, yyyy, hh, mi, ss] = m;
115	    const month = Number(mm);
116	    const day = Number(dd);
117	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
118	    return new Date(
119	      Number(yyyy),
120	      month - 1,
121	      day,
122	      Number(hh),
123	      Number(mi),
124	      ss ? Number(ss) : 0,
125	    );
126	  }
127	  const fallback = new Date(value);
128	  return Number.isNaN(fallback.getTime()) ? null : fallback;
129	}
130	
131	/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
132	export function timeHHMMFromIso(iso: string | null | undefined): string {
133	  if (!iso) return '—';
134	  const d = new Date(iso);
135	  if (Number.isNaN(d.getTime())) return '—';
136	  const hh = String(d.getHours()).padStart(2, '0');
137	  const mm = String(d.getMinutes()).padStart(2, '0');
138	  return `${hh}:${mm}`;
139	}
