226	// ─────────────────────────────────────────────────────────────────────────────
227	// Pró-rata da meta
228	// ─────────────────────────────────────────────────────────────────────────────
229	
230	/**
231	 * Fração linear do dia comercial já decorrida em `now`.
232	 *
233	 * - Antes da abertura → 0 (não há venda esperada ainda).
234	 * - Depois do fechamento → 1 (meta integral esperada).
235	 * - Dentro da janela → interpolação linear simples (pró-rata).
236	 */
237	export function businessDayFraction(
238	  now: Date,
239	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
240	): number {
241	  const { start, end } = hours;
242	  if (end <= start) {
243	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
244	    return now.getHours() >= end ? 1 : 0;
245	  }
246	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
247	  if (h <= start) return 0;
248	  if (h >= end) return 1;
249	  return (h - start) / (end - start);
250	}
251	
252	/**
253	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
254	 *
255	 * Retorna null quando não dá para calcular com honestidade:
256	 * - meta ausente/zerada (sem referência), ou
257	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
258	 */
259	export function pctOfProRataTarget(
260	  sold: number,
261	  dailyTarget: number | null | undefined,
262	  now: Date,
263	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
264	): number | null {
265	  if (dailyTarget == null || dailyTarget <= 0) return null;
266	  const fraction = businessDayFraction(now, hours);
267	  if (fraction <= 0) return null;
268	  return (sold / (dailyTarget * fraction)) * 100;
269	}
270	
271	/**
272	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
273	 * cujo dia de referência já encerrou.
274	 */
275	export function pctOfFullDayTarget(
276	  sold: number,
277	  dailyTarget: number | null | undefined,
278	): number | null {
279	  if (dailyTarget == null || dailyTarget <= 0) return null;
280	  return (sold / dailyTarget) * 100;
281	}
282	
283	// ─────────────────────────────────────────────────────────────────────────────
284	// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
285	// ─────────────────────────────────────────────────────────────────────────────
286	
287	/**
288	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
289	 * passada, período anterior do filtro…). Retorna null quando a base é
290	 * ausente ou não positiva — sem base honesta, sem número inventado.
291	 */
292	export function relativeDelta(
293	  current: number,
294	  base: number | null | undefined,
295	): number | null {
296	  if (base == null || base <= 0) return null;
297	  return ((current - base) / base) * 100;
298	}
299	
300	/**
301	 * Delta % vs MESMO DIA da semana anterior — caso particular de
302	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
303	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
304	 */
305	export function weekOverWeekDelta(
306	  current: number,
307	  lastWeek: number | null | undefined,
308	): number | null {
309	  return relativeDelta(current, lastWeek);
310	}
311	
312	/**
313	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
314	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
315	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
316	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
317	 * usada no pró-rata da meta, por consistência).
318	 *
319	 * Comparar dia parcial com dia completo inflava a queda de manhã.
320	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
321	 *
322	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
323	 * (fração 0 — não há ponto de comparação honesto).
324	 */
325	export function proRataDayBase(
326	  referenceDayTotal: number | null | undefined,
327	  now: Date,
328	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
329	): number | null {
330	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
331	  const fraction = businessDayFraction(now, hours);
332	  if (fraction <= 0) return null;
333	  return referenceDayTotal * fraction;
334	}
335	
336	/**
337	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
338	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
339	 * a API existente).
340	 */
341	export function proRataLastWeekBase(
342	  lastWeek: number | null | undefined,
343	  now: Date,
344	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
345	): number | null {
346	  return proRataDayBase(lastWeek, now, hours);
347	}
