349	// ─────────────────────────────────────────────────────────────────────────────
350	// RAG da loja
351	// ─────────────────────────────────────────────────────────────────────────────
352	
353	/** Entrada da classificação RAG de uma unidade. */
354	export interface StoreRagInput {
355	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
356	  stockOutCount: number;
357	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
358	  stockLowCount: number;
359	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
360	  pctMetaProRata: number | null;
361	  /** true quando a unidade tem venda ao vivo (canal Degust). */
362	  isLiveChannel: boolean;
363	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
364	  lastMovementAt: Date | string | null;
365	  /** Instante da avaliação. */
366	  now: Date;
367	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
368	  hours?: TvBusinessHours;
369	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
370	  noMovementThresholdHours?: number;
371	}
372	
373	/**
374	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
375	 *
376	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
377	 *   não faz sentido alertar madrugada sem bipagem.
378	 * - A referência é clampada ao início da janela de hoje: se a última
379	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
380	 */
381	export function hoursWithoutMovementInWindow(
382	  lastMovementAt: Date | string | null,
383	  now: Date,
384	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
385	): number | null {
386	  const fraction = businessDayFraction(now, hours);
387	  if (fraction <= 0 || fraction >= 1) return null;
388	  const windowStart = new Date(now);
389	  windowStart.setHours(hours.start, 0, 0, 0);
390	  const last = lastMovementAt
391	    ? new Date(lastMovementAt).getTime()
392	    : Number.NEGATIVE_INFINITY;
393	  const ref = Math.max(last, windowStart.getTime());
394	  return (now.getTime() - ref) / 3_600_000;
395	}
396	
397	/**
398	 * Classificação RAG de uma unidade (management-by-exception).
399	 *
400	 * Regras (design.md §1.6, ordem de precedência):
401	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
402	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
403	 *   manhã, quando o pró-rata ainda é instável).
404	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
405	 *   movimentação há mais que o threshold dentro da janela OU venda live com
406	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
407	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
408	 *   em canal live e com meta cadastrada (pct != null).
409	 * - OK: nenhum desvio — tela calma, sem cor.
410	 */
411	export function classifyStoreRag(input: StoreRagInput): {
412	  status: TvRagStatus;
413	  reasons: string[];
414	} {
415	  const hours = input.hours ?? TV_BUSINESS_HOURS;
416	  const noMovementThreshold =
417	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
418	  const reasons: string[] = [];
419	
420	  // ── Vermelho: só ruptura (item zerado em alerta) ──
421	  if (input.stockOutCount > 0) {
422	    reasons.push(
423	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
424	    );
425	    return { status: 'red', reasons };
426	  }
427	
428	  // ── Âmbar ──
429	  if (input.stockLowCount > 0) {
430	    reasons.push(
431	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
432	    );
433	  }
434	  const gapHours = hoursWithoutMovementInWindow(
435	    input.lastMovementAt,
436	    input.now,
437	    hours,
438	  );
439	  if (gapHours !== null && gapHours > noMovementThreshold) {
440	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
441	  }
442	  if (
443	    input.isLiveChannel &&
444	    input.pctMetaProRata !== null &&
445	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
446	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
447	  ) {
448	    reasons.push(
449	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
450	    );
451	  }
452	  if (reasons.length > 0) return { status: 'amber', reasons };
453	
454	  return { status: 'ok', reasons: [] };
455	}
456	
457	/** Entrada de {@link buildNoMovementException}. */
458	export interface NoMovementExceptionInput {
459	  lojaId: number;
460	  lojaNome: string;
461	  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
462	  lastMovementAt: Date | string | null;
463	  now: Date;
464	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
465	  hours?: TvBusinessHours;
466	  /** Threshold em horas (default lojas 3h; fábrica 2h). */
467	  thresholdHours?: number;
468	}
