470	/**
471	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
472	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
473	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
474	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
475	 * Retorna null quando não há gap acima do threshold dentro da janela.
476	 */
477	export function buildNoMovementException(
478	  input: NoMovementExceptionInput,
479	): TvException | null {
480	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
481	  const gap = hoursWithoutMovementInWindow(
482	    input.lastMovementAt,
483	    input.now,
484	    input.hours ?? TV_BUSINESS_HOURS,
485	  );
486	  if (gap === null || gap <= threshold) return null;
487	  return {
488	    id: `no-movement:${input.lojaId}`,
489	    kind: 'no-movement',
490	    severity: 'amber',
491	    lojaId: input.lojaId,
492	    lojaNome: input.lojaNome,
493	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
494	  };
495	}
