531	/**
532	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
533	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
534	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
535	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
536	 */
537	export function classifyStaleness(
538	  lastUpdatedAt: Date | string | number | null | undefined,
539	  expectedIntervalMs: number,
540	  now: Date,
541	): TvFreshnessLevel {
542	  if (lastUpdatedAt == null) return 'very-stale';
543	  const ts = new Date(lastUpdatedAt).getTime();
544	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
545	  const age = now.getTime() - ts;
546	  if (age < 2 * expectedIntervalMs) return 'fresh';
547	  if (age < 6 * expectedIntervalMs) return 'stale';
548	  return 'very-stale';
549	}
550	
551	/**
552	 * Monta o freshness consolidado a partir dos timestamps CRUS de última
553	 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
554	 *
555	 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
556	 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
557	 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
558	 * parar de avançar além de 2× o intervalo esperado.
559	 */
560	export function buildFreshness(
561	  liveUpdatedAtMs: number,
562	  stockUpdatedAtMs: number,
563	  intervals: { liveMs: number; slowMs: number },
564	  now: Date,
565	): TvFreshness {
566	  const liveUpdatedAt =
567	    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
568	  const stockUpdatedAt =
569	    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
570	  return {
571	    vendasLive: {
572	      updatedAt: liveUpdatedAt,
573	      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
574	      expectedIntervalMs: intervals.liveMs,
575	    },
576	    estoque: {
577	      updatedAt: stockUpdatedAt,
578	      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
579	      expectedIntervalMs: intervals.slowMs,
580	    },
581	    geradoEm: now.toISOString(),
582	  };
583	}
