683	/**
684	 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
685	 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
686	 * query). Regras (critério existente do projeto, sem schema novo):
687	 * - zerado (vermelho): quantidade ≤ 0 com mínimo definido (positivo);
688	 * - abaixo do mínimo (âmbar): quantidade entre 0 exclusivo e o mínimo.
689	 */
690	export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
691	  const out = new Map<number, StockDetail>();
692	  for (const row of rows) {
693	    if (row.loja_id == null) continue;
694	    const min = row.quantidade_minima ?? 0;
695	    if (min <= 0) continue; // sem mínimo definido → sem alerta
696	    const qty = row.quantidade_atual ?? 0;
697	    if (qty >= min) continue; // dentro do normal
698	    let detail = out.get(row.loja_id);
699	    if (!detail) {
700	      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
701	      out.set(row.loja_id, detail);
702	    }
703	    const zerado = qty <= 0;
704	    if (zerado) detail.zerados += 1;
705	    else detail.abaixoMinimo += 1;
706	    detail.itens.push({
707	      produtoNome: row.produtoNome,
708	      quantidade: qty,
709	      quantidadeMinima: min,
710	      zerado,
711	    });
712	  }
713	  return out;
714	}
