721	  detailByLoja: Map<number, StockDetail>,
722	  lojaNomeById: Map<number, string>,
723	): TvException[] {
724	  const out: TvException[] = [];
725	  for (const [lojaId, detail] of detailByLoja) {
726	    const lojaNome = lojaNomeById.get(lojaId) ?? `Loja ${lojaId}`;
727	    for (const item of detail.itens) {
728	      out.push({
729	        id: `${item.zerado ? 'stock-out' : 'stock-low'}:${lojaId}:${item.produtoNome}`,
730	        kind: item.zerado ? 'stock-out' : 'stock-low',
731	        severity: item.zerado ? 'red' : 'amber',
732	        lojaId,
733	        lojaNome,
734	        message: item.zerado
735	          ? `${item.produtoNome} zerado — ${lojaNome}`
736	          : `${item.produtoNome} abaixo do mínimo (${item.quantidade}/${item.quantidadeMinima}) — ${lojaNome}`,
737	        produtoNome: item.produtoNome,
738	        quantidade: item.quantidade,
739	        quantidadeMinima: item.quantidadeMinima,
740	      });
741	    }
742	  }
743	  return out;
