790	/**
791	 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
792	 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
793	 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
794	 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
795	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
796	 * o drill-down, a lista completa.
797	 */
798	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
799	  const missingFraction = (c: TvCriticalItem): number =>
800	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
801	  return items
802	    .map<TvCriticalItem>((i) => ({
803	      nome: i.produtoNome,
804	      quantidade: i.quantidade,
805	      minima: i.quantidadeMinima,
806	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
807	    }))
808	    .sort((a, b) => {
809	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
810	      const diff = missingFraction(b) - missingFraction(a);
811	      if (diff !== 0) return diff;
812	      return a.nome.localeCompare(b.nome, 'pt-BR');
813	    });
814	}
