934	// ─────────────────────────────────────────────────────────────────────────────
935	// Paginação PostgREST (loop genérico com fetcher injetado — sem I/O próprio)
936	// ─────────────────────────────────────────────────────────────────────────────
937	
938	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
939	export interface TvPageResult<T> {
940	  data: T[] | null;
941	  error: { message: string } | null;
942	}
943	
944	/**
945	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
946	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
947	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
948	 *
949	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
950	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
951	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
952	 * sobreporem entre requests.
953	 */
954	export async function fetchAllPages<T>(
955	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
956	  pageSize = 1000,
957	): Promise<T[]> {
958	  const all: T[] = [];
959	  let offset = 0;
960	  for (;;) {
961	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
962	    if (error) throw error;
963	    const rows = data ?? [];
964	    all.push(...rows);
965	    if (rows.length < pageSize) return all;
966	    offset += pageSize;
967	  }
968	}
