/**
 * Normaliza um valor de `produtos_master.setor` para comparação: trim,
 * minúsculas e remoção de acentos (NFD). O banco tem caixa/acentuação
 * inconsistentes no MESMO setor (ex.: "CÂMARA FRIA" e "Câmara Fria") —
 * toda comparação de setor DEVE passar por aqui.
 */
export function normalizeSetor(value: string | null | undefined): string {
  return (value ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .trim()
    .toLowerCase();
}

