/** Exportado para o `useTvStoreDetail` compartilhar a MESMA query/cache. */
export async function fetchStockAlerts(): Promise<StockRow[]> {
  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas
  // candidatas hoje). Paginação obrigatória: o PostgREST corta em 1000 linhas
  // mesmo com `.limit()` maior — `.order('id')` garante páginas estáveis.
  const data = await fetchAllPages((from, to) =>
    supabase
      .from('estoque')
      .select(
        'loja_id, quantidade_atual, quantidade_minima, produto_master:produtos_master!inner(nome, ativo)',
      )
      .eq('produto_master.ativo', true)
      .gt('quantidade_minima', 0)
      .or('oculto.is.null,oculto.eq.false')
      .order('id')
      .range(from, to),
  );
  return data.map((row) => ({
    loja_id: row.loja_id,
    quantidade_atual: row.quantidade_atual,
    quantidade_minima: row.quantidade_minima,
    produtoNome: row.produto_master?.nome ?? '(sem nome)',
  }));
}

