describe('normalizeSetor + isTvAlertSetor (regra do CTO 2026-06-05)', () => {
  it('normaliza caixa, espaços e acentos (inconsistência real do banco)', () => {
    expect(normalizeSetor('  CÂMARA FRIA ')).toBe('camara fria');
    expect(normalizeSetor('Câmara Fria')).toBe(normalizeSetor('CÂMARA FRIA'));
    expect(normalizeSetor(null)).toBe('');
    expect(normalizeSetor(undefined)).toBe('');
  });

  it('aceita só igualdade EXATA com TV_ALERT_SETOR — nunca prefixo', () => {
    expect(TV_ALERT_SETOR).toBe('PRODUTOS');
    expect(isTvAlertSetor('PRODUTOS')).toBe(true);
    expect(isTvAlertSetor('Produtos ')).toBe(true); // caixa/espaço divergente conta
    expect(isTvAlertSetor(' produtos')).toBe(true);
    // Armadilha real: "PRODUTOS DE LIMPEZA" começa com "PRODUTOS" e NÃO conta
    expect(isTvAlertSetor('PRODUTOS DE LIMPEZA')).toBe(false);
    expect(isTvAlertSetor('EMBALAGENS')).toBe(false);
    expect(isTvAlertSetor('INSUMOS')).toBe(false);
    expect(isTvAlertSetor(null)).toBe(false);
  });
});

