    { loja_id: null, quantidade_atual: 0, quantidade_minima: 5, produtoNome: 'ÓRFÃO', setor: 'PRODUTOS' },
    // Regra do CTO 2026-06-05: zerados FORA do setor PRODUTOS nunca alertam
    { loja_id: 2, quantidade_atual: 0, quantidade_minima: 5, produtoNome: 'SACO KRAFT', setor: 'EMBALAGENS' },
    { loja_id: 2, quantidade_atual: 0, quantidade_minima: 5, produtoNome: 'DETERGENTE', setor: 'PRODUTOS DE LIMPEZA' },
    { loja_id: 4, quantidade_atual: 0, quantidade_minima: 5, produtoNome: 'MORANGO', setor: null }, // sem setor → fora
  ];

  it('classifica zerado vs abaixo do mínimo só com mínimo definido', () => {
    const summary = buildStockSummary(rows);
    expect(summary.get(2)).toMatchObject({ zerados: 1, abaixoMinimo: 1 });
    expect(summary.get(4)).toMatchObject({ zerados: 1, abaixoMinimo: 0 });
    expect(summary.size).toBe(2);
  });

  it('só o setor PRODUTOS alerta — EMBALAGENS/LIMPEZA/null zerados ficam fora', () => {
    const summary = buildStockSummary(rows);
    const nomesLoja2 = summary.get(2)?.itens.map((i) => i.produtoNome) ?? [];
    expect(nomesLoja2).not.toContain('SACO KRAFT'); // EMBALAGENS zerado ≠ alerta
    expect(nomesLoja2).not.toContain('DETERGENTE'); // prefixo "PRODUTOS" não basta
    expect(nomesLoja2).toContain('COOKIE'); // "Produtos " normalizado conta
    const nomesLoja4 = summary.get(4)?.itens.map((i) => i.produtoNome) ?? [];
    expect(nomesLoja4).not.toContain('MORANGO'); // setor null fica fora
  });

